# Implement Jaro-Winkler and test
def jaro(s1,s2):
    if s1==s2:
        return 1.0
    len1=len(s1); len2=len(s2)
    if len1==0 or len2==0:
        return 0.0
    match_distance = max(len1,len2)//2 -1
    s1_matches=[False]*len1
    s2_matches=[False]*len2
    matches=0
    transpositions=0
    for i in range(len1):
        start=max(0,i-match_distance)
        end=min(i+match_distance+1,len2)
        for j in range(start,end):
            if s2_matches[j]:
                continue
            if s1[i]!=s2[j]:
                continue
            s1_matches[i]=True
            s2_matches[j]=True
            matches+=1
            break
    if matches==0:
        return 0.0
    k=0
    for i in range(len1):
        if not s1_matches[i]:
            continue
        while not s2_matches[k]:
            k+=1
        if s1[i]!=s2[k]:
            transpositions+=1
        k+=1
    transpositions//=2
    return (matches/len1 + matches/len2 + (matches-transpositions)/matches)/3.0

def jaro_winkler(s1,s2,p=0.1):
    j=jaro(s1,s2)
    # prefix up to 4
    prefix=0
    for i in range(min(len(s1),len(s2),4)):
        if s1[i]==s2[i]:
            prefix+=1
        else:
            break
    return j + prefix*p*(1-j)

