# ==================== Database Layer ====================

# DuckDB type mapping
def normalize_duck_type(typ):
    if typ is None:
        return "INTEGER"
    t = typ.strip().upper()
    # Remove extra spaces, handle DECIMAL(3,2) etc.
    # Keep as is for storage, but normalize for display?
    return t

def duck_display_type(typ):
    # Convert stored type to duckbox display (lowercase, e.g., int32, varchar, boolean, double, decimal(3,2))
    if typ is None:
        return "int32"
    t = typ.strip()
    up = t.upper()
    # Handle DECIMAL(3,2) -> decimal(3,2)
    if up.startswith("DECIMAL"):
        # Extract params
        m = re.match(r"DECIMAL\s*(\(.*\))?", t, re.I)
        if m and m.group(1):
            return "decimal" + m.group(1).replace(" ", "")
        return "decimal"
    if up in ("INTEGER", "INT", "INT4", "SIGNED", "INT32"):
        return "int32"
    if up in ("BIGINT", "INT8", "LONG", "INT64"):
        return "int64"
    if up in ("SMALLINT", "INT16", "SHORT"):
        return "int16"
    if up in ("TINYINT", "INT8_", "INT8TINY"):
        return "int8"
